DROP DATABASE IF EXISTS hospital_system;
CREATE DATABASE hospital_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hospital_system;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL,employee_no VARCHAR(40),phone VARCHAR(30),is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE patients(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,mrn VARCHAR(30) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,nik VARCHAR(30),gender VARCHAR(20) NOT NULL,birth_date DATE NOT NULL,blood_type VARCHAR(5),phone VARCHAR(30),address TEXT,emergency_contact VARCHAR(120),emergency_phone VARCHAR(30),insurance VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE doctors(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,department VARCHAR(100),specialty VARCHAR(100),license_no VARCHAR(80));
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,appointment_date DATETIME NOT NULL,status VARCHAR(30) DEFAULT 'booked',queue_no VARCHAR(20),visit_type VARCHAR(30) DEFAULT 'new',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE registrations(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,registered_by INT NOT NULL,registration_date DATETIME DEFAULT CURRENT_TIMESTAMP,visit_type VARCHAR(30) DEFAULT 'outpatient',guarantor VARCHAR(80),complaint TEXT,status VARCHAR(30) DEFAULT 'registered');
CREATE TABLE encounters(id INT AUTO_INCREMENT PRIMARY KEY,appointment_id INT NULL,patient_id INT NOT NULL,doctor_id INT NOT NULL,encounter_date DATETIME DEFAULT CURRENT_TIMESTAMP,chief_complaint TEXT,subjective TEXT,objective TEXT,assessment TEXT,plan TEXT,diagnosis_code VARCHAR(30),diagnosis_name VARCHAR(180),allergies TEXT,clinical_status VARCHAR(30) DEFAULT 'draft',signed_at DATETIME NULL);
CREATE TABLE encounter_addenda(id INT AUTO_INCREMENT PRIMARY KEY,encounter_id INT NOT NULL,author_user_id INT NOT NULL,note TEXT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE nursing_notes(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,encounter_id INT NULL,nurse_id INT NOT NULL,recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,assessment TEXT,intervention TEXT,evaluation TEXT,fall_risk VARCHAR(20) DEFAULT 'low',pain_score INT DEFAULT 0,notes TEXT);
CREATE TABLE vital_signs(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,recorded_by INT NOT NULL,recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,temperature DECIMAL(4,1),systolic INT,diastolic INT,pulse INT,respiratory_rate INT,spo2 DECIMAL(5,2),weight DECIMAL(6,2),height DECIMAL(6,2),pain_score INT DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'normal',notes TEXT);
CREATE TABLE medicines(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL,category VARCHAR(80),unit VARCHAR(30) NOT NULL,stock INT NOT NULL DEFAULT 0,min_stock INT NOT NULL DEFAULT 10,expiry_date DATE,price DECIMAL(12,2) NOT NULL DEFAULT 0,is_active TINYINT(1) DEFAULT 1);
CREATE TABLE prescriptions(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor_id INT NOT NULL,encounter_id INT NULL,status VARCHAR(30) DEFAULT 'pending',notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,dispensed_at DATETIME NULL);
CREATE TABLE prescription_items(id INT AUTO_INCREMENT PRIMARY KEY,prescription_id INT NOT NULL,medicine_id INT NOT NULL,quantity INT NOT NULL,dosage VARCHAR(160) NOT NULL,route VARCHAR(50) DEFAULT 'oral',duration VARCHAR(50));
CREATE TABLE cpoe_orders(id INT AUTO_INCREMENT PRIMARY KEY,encounter_id INT NOT NULL,patient_id INT NOT NULL,ordered_by INT NOT NULL,order_type VARCHAR(30) NOT NULL,priority VARCHAR(20) DEFAULT 'routine',order_name VARCHAR(180) NOT NULL,clinical_indication TEXT,instructions TEXT,status VARCHAR(30) DEFAULT 'ordered',ordered_at DATETIME DEFAULT CURRENT_TIMESTAMP,completed_at DATETIME NULL);
CREATE TABLE lab_results(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,test_name VARCHAR(180) NOT NULL,result_value VARCHAR(120),unit VARCHAR(40),reference_range VARCHAR(80),flag VARCHAR(20) DEFAULT 'normal',verified_by INT NULL,result_notes TEXT,reported_at DATETIME NULL);
CREATE TABLE radiology_results(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,modality VARCHAR(80),technique TEXT,findings TEXT,impression TEXT,reported_by INT NULL,reported_at DATETIME NULL);
CREATE TABLE invoices(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,invoice_no VARCHAR(40) UNIQUE NOT NULL,total DECIMAL(12,2) NOT NULL DEFAULT 0,status VARCHAR(30) DEFAULT 'unpaid',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoice_items(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,description VARCHAR(200) NOT NULL,qty INT NOT NULL DEFAULT 1,price DECIMAL(12,2) NOT NULL);
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,invoice_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(30) NOT NULL,paid_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,received_by INT NULL);
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(120) NOT NULL,module VARCHAR(80),record_id INT NULL,description TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
